 "content": "def transform(grid):
    """Rotate the four diagonal markers clockwise around each 2x2 block,
    then extend each marker diagonally outward to the grid edge."""
    h, w = len(grid), len(grid[0])
    out = [[0] * w for _ in range(h)]

    # Preserve all 2x2 objects.
    blocks = []
    for r in range(h - 1):
        for c in range(w - 1):
            if all(grid[rr][cc] == 2 for rr, cc in
                   ((r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1))):
                blocks.append((r, c))
                for rr, cc in ((r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1)):
                    out[rr][cc] = 2

    # Source marker positions: upper-left, upper-right, lower-left, lower-right.
    # Destination rays (clockwise rotation): UL<-LL, UR<-UL, LL<-LR, LR<-UR.
    for r, c in blocks:
        sources = {
            "ul": grid[r - 1][c - 1] if r > 0 and c > 0 else 0,
            "ur": grid[r - 1][c + 2] if r > 0 and c + 2 < w else 0,
            "ll": grid[r + 2][c - 1] if r + 2 < h and c > 0 else 0,
            "lr": grid[r + 2][c + 2] if r + 2 < h and c + 2 < w else 0,
        }
        rays = (
            (r - 1, c - 1, -1, -1, sources["ll"]),
            (r - 1, c + 2, -1,  1, sources["ul"]),
            (r + 2, c - 1,  1, -1, sources["lr"]),
            (r + 2, c + 2,  1,  1, sources["ur"]),
        )
        for rr, cc, dr, dc, color in rays:
            if not color:
                continue
            while 0 <= rr < h and 0 <= cc < w:
                if out[rr][cc] == 0:
                    out[rr][cc] = color
                rr += dr
                cc += dc

    return out
